CREATE TABLE IF NOT EXISTS device (id VARCHAR(64) PRIMARY KEY, model VARCHAR(64) NOT NULL, location VARCHAR(100) NOT NULL, config_version VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS maintenance_case (id VARCHAR(64) PRIMARY KEY, device_id VARCHAR(64) NOT NULL REFERENCES device(id), phenomenon VARCHAR(300) NOT NULL, cause VARCHAR(500) NOT NULL, action_summary VARCHAR(1000) NOT NULL, result VARCHAR(500) NOT NULL, review_status VARCHAR(20) NOT NULL, reviewer VARCHAR(100), reviewed_at VARCHAR(40), created_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS knowledge_document (id VARCHAR(64) PRIMARY KEY, title VARCHAR(200) NOT NULL, version VARCHAR(40) NOT NULL, model VARCHAR(64) NOT NULL, config_version VARCHAR(40) NOT NULL, section VARCHAR(100) NOT NULL, content VARCHAR(3000) NOT NULL, status VARCHAR(20) NOT NULL);
CREATE TABLE IF NOT EXISTS question_trace (id VARCHAR(64) PRIMARY KEY, question VARCHAR(1000) NOT NULL, device_id VARCHAR(64), response_json CLOB NOT NULL, created_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS feedback (id VARCHAR(64) PRIMARY KEY, trace_id VARCHAR(64) NOT NULL REFERENCES question_trace(id), case_id VARCHAR(64) NOT NULL REFERENCES maintenance_case(id), created_at VARCHAR(40) NOT NULL);
